steps.script:
for i in range(20):
	if TutorialManager.current_step_id() == "deploy_grots":
		break
	TutorialManager.skip_step()
return TutorialManager.current_step_id()

var b = tree.root.get_node_or_null("Main/RollOffDialog/Content/ButtonBar/RollButton")
if b == null:
	return "no roll button"
b.pressed.emit()
return "pressed"

var rd = tree.root.get_node_or_null("Main/RollOffDialog")
if not rd.has_meta("tutorial_exit_button"):
	return "missing"
var b = rd.get_meta("tutorial_exit_button")
return "%s|%s" % [str(b.text), str(b.is_visible_in_tree())]

var rd = tree.root.get_node_or_null("Main/RollOffDialog")
var b = rd.get_meta("tutorial_exit_button")
var roll = tree.root.get_node_or_null("Main/RollOffDialog/Content/ButtonBar/RollButton")
b.grab_focus()
var on_hatch = rd.gui_get_focus_owner() == b
var back = b.find_valid_focus_neighbor(SIDE_TOP)
roll.grab_focus()
return "%s|%s" % [str(on_hatch), str(back == roll)]

var stray = []
for c in tree.root.get_children():
	if c is Window and c != tree.root and c.visible:
		stray.append(str(c.name))
return stray.size()
